function Progress() {
  const [w, setW] = useState(0);
  useEffect(() => { const on = () => { const h = document.documentElement; const max = h.scrollHeight - h.clientHeight; setW(max > 0 ? (h.scrollTop / max) * 100 : 0); }; on(); window.addEventListener("scroll", on); window.addEventListener("resize", on); return () => { window.removeEventListener("scroll", on); window.removeEventListener("resize", on); }; }, []);
  return <div className="progress" style={{ width: w + "%" }} />;
}
