function Contact() {
  const [form, setForm] = useState({ name: "", email: "", org: "", reason: "", message: "", consent: false });
  const [errors, setErrors] = useState({}); const [sent, setSent] = useState(false); const hp = useRef("");
  const set = (k) => (e) => setForm({ ...form, [k]: e.target.type === "checkbox" ? e.target.checked : e.target.value });
  const validate = () => { const er = {}; if (form.name.trim().length < 2) er.name = "Please enter your name (2–80 characters)."; if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(form.email)) er.email = "Please enter a valid work email."; if (!form.reason) er.reason = "Please choose a reason for contact."; if (form.message.trim().length < 30) er.message = "Please write at least 30 characters."; if (!form.consent) er.consent = "Please confirm agreement to the privacy notice."; setErrors(er); return Object.keys(er).length === 0; };
  const submit = () => { if (hp.current) return; if (validate()) setSent(true); };
  return (
    <section className="section"><div className="container read">
      <Reveal><p className="eyebrow">Contact</p><h1 className="h1" style={{ marginTop: 10 }}>Let's discuss the product problem you are solving.</h1>
        <p className="lead" style={{ marginTop: 14 }}>I'm open to Senior, Lead and Principal Product Manager opportunities, remote or relocation, across fintech, health tech, marketplaces, platform transformation and AI. Design-led throughout.</p></Reveal>
      {sent ? (<div className="notice" style={{ marginTop: 28 }}><Check size={18} style={{ flexShrink: 0 }} /><span>Thank you. Your message has been sent successfully. I'll reply to {form.email}.</span></div>) : (
        <Reveal className="card" style={{ marginTop: 28 }}>
          <input type="text" tabIndex={-1} aria-hidden="true" autoComplete="off" style={{ position: "absolute", left: "-9999px" }} onChange={(e) => (hp.current = e.target.value)} />
          <div className="field"><label htmlFor="name">Name</label><input id="name" value={form.name} onChange={set("name")} aria-invalid={!!errors.name} aria-describedby="name-e" />{errors.name && <div id="name-e" className="err">{errors.name}</div>}</div>
          <div className="field"><label htmlFor="email">Work email</label><input id="email" type="email" value={form.email} onChange={set("email")} aria-invalid={!!errors.email} aria-describedby="email-e" />{errors.email && <div id="email-e" className="err">{errors.email}</div>}</div>
          <div className="field"><label htmlFor="org">Organisation <span className="muted" style={{ fontWeight: 400 }}>(optional)</span></label><input id="org" value={form.org} onChange={set("org")} /></div>
          <div className="field"><label htmlFor="reason">Reason for contact</label><select id="reason" value={form.reason} onChange={set("reason")} aria-invalid={!!errors.reason} aria-describedby="reason-e"><option value="">Select a reason…</option>{["Role opportunity", "Consulting", "Product collaboration", "UI/UX / design", "Speaking", "Other"].map((o) => <option key={o} value={o}>{o}</option>)}</select>{errors.reason && <div id="reason-e" className="err">{errors.reason}</div>}</div>
          <div className="field"><label htmlFor="message">Message</label><textarea id="message" rows={5} value={form.message} onChange={set("message")} aria-invalid={!!errors.message} aria-describedby="message-e" />{errors.message && <div id="message-e" className="err">{errors.message}</div>}</div>
          <div className="check"><input id="consent" type="checkbox" checked={form.consent} onChange={set("consent")} aria-describedby="consent-e" /><label htmlFor="consent" style={{ fontWeight: 400, fontSize: 14 }}>I agree that my details may be used to respond to this enquiry, in line with the privacy notice.</label></div>
          {errors.consent && <div id="consent-e" className="err">{errors.consent}</div>}
          <div style={{ marginTop: 22 }}><Btn onClick={submit} icon={ArrowRight}>Send message</Btn></div>
        </Reveal>
      )}
      <div style={{ marginTop: 32, display: "flex", gap: 16, flexWrap: "wrap" }}>
        <a className="btn btn-secondary" href={"mailto:" + BRAND.email}><Mail size={16} /> {BRAND.email}</a>
        <a className="btn btn-secondary" href={BRAND.linkedin} target="_blank" rel="noopener noreferrer"><Linkedin size={16} /> LinkedIn</a>
      </div>
    </div></section>
  );
}

function Privacy() {
  return (
    <section className="section"><div className="container read">
      <Reveal><p className="eyebrow">Privacy</p><h1 className="h1" style={{ marginTop: 10 }}>Privacy and confidentiality</h1>
        <p className="lead" style={{ marginTop: 14 }}>This portfolio collects only the information submitted through the contact form and limited privacy-conscious analytics required to understand page and case-study performance. It does not sell personal information or use contact details for unrelated marketing.</p></Reveal>
      <ul className="cs-body" style={{ paddingLeft: 20, marginTop: 20 }}>
        <li>Contact-form data (name, email, organisation, reason and message) is used only to respond to your enquiry.</li>
        <li>Analytics is privacy-conscious and does not receive message content, email addresses or personally identifiable information.</li>
        <li>Enquiry details are retained only as long as needed to respond and follow up.</li>
        <li>You can request deletion of your enquiry data by emailing {BRAND.email}.</li>
      </ul>
      <h2 className="h2" style={{ marginTop: 40 }}>Confidentiality</h2>
      <p style={{ marginTop: 12 }}>Case studies are sanitised or anonymised. Customer data, production endpoints, credentials, internal correspondence, contracts, commercial terms and restricted system artefacts are never published.</p>
    </div></section>
  );
}

export default function App() {
  const [route, go] = useRoute();
  return (
    <div className="po-root">
      <style>{`@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');` + STYLE}</style>
      <Progress />
      <a href="#main" className="skip">Skip to content</a>
      <Header route={route} go={go} />
      <main id="main">
        {route.name === "home" && <Home go={go} />}
        {route.name === "about" && <About go={go} />}
        {route.name === "work" && <Work go={go} />}
        {route.name === "case" && <CaseDetail slug={route.slug} go={go} />}
        {route.name === "experience" && <Experience />}
        {route.name === "expertise" && <Expertise go={go} />}
        {route.name === "resume" && <Resume />}
        {route.name === "contact" && <Contact />}
        {route.name === "privacy" && <Privacy />}
      </main>
      <Footer go={go} />
    </div>
  );
}
